```go
package react

type reactor struct {
	cells []*cell
}

type cell struct {
	value       int
	compute     func() int
	dependencies []Cell
	dependents  []*cell
	callbacks   []func(int)
}

type canceler struct {
	cell  *cell
	index int
}

func New() Reactor {
	return &reactor{}
}

func (r *reactor) CreateInput(initial int) InputCell {
	c := &cell{value: initial}
	r.cells = append(r.cells, c)
	return c
}

func (r *reactor) CreateCompute1(dep Cell, compute func(int) int) ComputeCell {
	c := &cell{
		compute:      func() int { return compute(dep.Value()) },
		dependencies: []Cell{dep},
	}
	dep.(*cell).dependents = append(dep.(*cell).dependents, c)
	r.cells = append(r.cells, c)
	c.value = c.compute()
	return c
}

func (r *reactor) CreateCompute2(dep1, dep2 Cell, compute func(int, int) int) ComputeCell {
	c := &cell{
		compute:      func() int { return compute(dep1.Value(), dep2.Value()) },
		dependencies: []Cell{dep1, dep2},
	}
	dep1.(*cell).dependents = append(dep1.(*cell).dependents, c)
	dep2.(*cell).dependents = append(dep2.(*cell).dependents, c)
	r.cells = append(r.cells, c)
	c.value = c.compute()
	return c
}

func (c *cell) Value() int { return c.value }

func (c *cell) SetValue(value int) {
	c.value = value
	// BFS through dependents
	dirty := []*cell{}
	seen := map[*cell]bool{}
	queue := []*cell{c}
	for len(queue) > 0 {
		cur := queue[0]
		queue = queue[1:]
		for _, d := range cur.dependents {
			if !seen[d] {
				seen[d] = true
				dirty = append(dirty, d)
				queue = append(queue, d)
			}
		}
	}
	// Recompute in BFS order (topological order)
	for _, d := range dirty {
		d.value = d.compute()
	}
	// Call callbacks for cells whose value changed
	for _, d := range dirty {
		for _, cb := range d.callbacks {
			cb(d.value)
		}
	}
}
```

