package react

// reactor manages a set of linked cells.
type reactor struct {
	cells []*cell
}

// cell is a holder of a value. Input cells can be set directly; compute
// cells derive their value from their dependencies via a compute function.
type cell struct {
	value      int
	compute    func() int
	dependents []*cell
	callbacks  []func(int)
}

// canceler removes a previously added callback from a compute cell.
type canceler struct {
	cell  *cell
	index int
}

// New creates a new empty reactor.
func New() Reactor {
	return &reactor{}
}

// CreateInput creates an input cell with the given initial value.
func (r *reactor) CreateInput(initial int) InputCell {
	c := &cell{value: initial}
	r.cells = append(r.cells, c)
	return c
}

// CreateCompute1 creates a compute cell whose value is computed from one
// dependency cell.
func (r *reactor) CreateCompute1(dep Cell, compute func(int) int) ComputeCell {
	return r.newComputeCell([]Cell{dep}, func() int {
		return compute(dep.Value())
	})
}

// CreateCompute2 creates a compute cell whose value is computed from two
// dependency cells.
func (r *reactor) CreateCompute2(dep1, dep2 Cell, compute func(int, int) int) ComputeCell {
	return r.newComputeCell([]Cell{dep1, dep2}, func() int {
		return compute(dep1.Value(), dep2.Value())
	})
}

// newComputeCell creates a compute cell linked to its dependencies and
// registers it as a dependent of each of them.
func (r *reactor) newComputeCell(deps []Cell, compute func() int) *cell {
	c := &cell{compute: compute}
	for _, d := range deps {
		dc := d.(*cell)
		dc.dependents = append(dc.dependents, c)
	}
	r.cells = append(r.cells, c)
	c.value = c.compute()
	return c
}

// Value returns the current value of the cell.
func (c *cell) Value() int {
	return c.value
}

// SetValue sets the value of an input cell and propagates the change to all
// dependent cells, recomputing them in topological order. Callbacks of
// compute cells are invoked only if their value in the new stable state
// differs from the previous stable state.
func (c *cell) SetValue(value int) {
	if c.value == value {
		return
	}
	c.value = value

	// Collect all affected compute cells via BFS. BFS order is a valid
	// topological order, so recomputing in this order yields a stable state.
	var dirty []*cell
	seen := make(map[*cell]bool)
	queue := []*cell{c}
	for len(queue) > 0 {
		current := queue[0]
		queue = queue[1:]
		for _, d := range current.dependents {
			if !seen[d] {
				seen[d] = true
				dirty = append(dirty, d)
				queue = append(queue, d)
			}
		}
	}

	for _, d := range dirty {
		old := d.value
		d.value = d.compute()
		if d.value != old {
			for _, cb := range d.callbacks {
				if cb != nil {
					cb(d.value)
				}
			}
		}
	}
}

// AddCallback adds a callback that is invoked when the cell's value changes
// in a new stable state. It returns a Canceler that removes the callback.
func (c *cell) AddCallback(callback func(int)) Canceler {
	c.callbacks = append(c.callbacks, callback)
	return &canceler{cell: c, index: len(c.callbacks) - 1}
}

// Cancel removes the callback. Cancelling multiple times is a no-op.
func (c *canceler) Cancel() {
	if c.cell.callbacks[c.index] == nil {
		return
	}
	c.cell.callbacks[c.index] = nil
}
